import { BaseRpcContext } from './base-rpc.context.js';
/**
 * @publicApi
 */
export class RmqContext extends BaseRpcContext {
    constructor(args) {
        super(args);
    }
    /**
     * Returns the original message (with properties, fields, and content).
     */
    getMessage() {
        return this.args[0];
    }
    /**
     * Returns the reference to the original RMQ channel.
     */
    getChannelRef() {
        return this.args[1];
    }
    /**
     * Returns the name of the pattern.
     */
    getPattern() {
        return this.args[2];
    }
}
